INSERT INTO `movies` VALUES (1,'Án Mạng Karaoke','an-mang-karaoke','Một người hàng xóm mê hát karaoke bất ngờ bị sát hại trong căn homestay thiền biệt lập trên núi, khiến chuyến hành hương của một xóm nhỏ bị biến thành trò chơi đấu trí bất đắc dĩ. Phim có suất chiếu sớm ngày 21/10/2026 và khởi chiếu chính thức ngày 30/10/2026.','Hoàng Lê','Vân Dung, Đoàn Thiên Ân, Đại Nghĩa',96,'2026-10-30','T16','posters/an-mang-karaoke-1.webp','https://www.youtube.com/watch?v=SpBeFk9L7yY','now_showing','2026-10-27 08:46:51','2026-10-27 08:46:51',NULL),(2,'Trại Buôn Người','trai-buon-nguoi','Vì cứu em gái sa bẫy buôn người ở vùng biên giới, Ny (Steven Nguyễn) cùng bạn thân bị bắt làm nô dịch trong sào huyệt lừa đảo tàn bạo. Tại đây, họ cùng các trinh sát nằm vùng và các nạn nhân hứng chịu bi kịch thể xác âm thầm lập kế hoạch trốn thoát.','Toni Dương Bảo Anh','Steven Nguyễn, Quách Ngọc Ngoan, Huỳnh Minh Kiên',135,'2026-09-25','T18','posters/trai-buon-nguoi.webp','https://www.youtube.com/watch?v=3uzzMdKQImk','now_showing','2026-10-27 08:46:51','2026-10-27 08:46:51',NULL),(3,'Quỷ Ăn Tạng 4: Hổ Tinh','quy-an-tang-4-ho-tinh','Phim đưa khán giả trở về thời điểm Yak (Nadech Kugimiya thủ vai) lần đầu gặp Trung sĩ Paphan (Ongart Cheamcharoenpornkul thủ vai), khi cả hai cùng tham gia nhiệm vụ nguy hiểm nhằm tìm kiếm tiểu đội tình báo mất tích giữa khu rừng bí ẩn. Dẫn đầu đội tìm kiếm tiến sâu vào rừng, Yak và Trung sĩ Paphan bất ngờ chạm trán Hổ Tinh - sinh vật siêu nhiên mang hình hài mãnh thú, chuyên săn và ăn thịt người, đồng thời có khả năng biến hóa thành nhiều hình dạng để thao túng con mồi. Trước mối đe dọa chưa từng đối mặt, cả hai buộc phải hợp tác chiến đấu và sinh tồn, đồng thời tìm ra bí mật ẩn sâu trong khu rừng trước khi trở thành những nạn nhân tiếp theo.','Narit Yuvaboon, Thanadet Pradit, Chalit Krileadmongkon','Nadech Kugimiya, Ong-art Cheamcharoenpornkul, Maylada Susri, Wichapas Sumettikul, Sahajak Boonthanakit, Akarin Akaranitimaytharatt, Dan Chupong, Chanintorn Jitpreeda, Natthachai Sirinanthachot, Pavarit Mongkolpisit',111,'2026-10-16','T18','posters/quy-an-tang-4-ho-tinh.webp','https://www.youtube.com/watch?v=rpFS0tXzVro','now_showing','2026-10-27 08:46:51','2026-10-27 08:46:51',NULL),(4,'Cõi Nguyền','coi-nguyen','Dựa trên loạt truyền thuyết đô thị gây chấn động Nhật Bản, Cõi Nguyền bắt nguồn từ lời nguyền của một người phụ nữ kỳ bí đã ám cô gái trẻ tên Riko chỉ với một dòng tin nhắn: “Tất cả mọi người đều đáng chết”. Kể từ thời khắc lời nguyền linh ứng, lần lượt tất cả những người bạn xung quanh Riko đều chết một cách bí ẩn và các vụ án mạng đều được đưa ra kết luận với nguyên nhân tử vong là “tự sát”. Tuy nhiên, điều kinh hoàng hơn là số lượng những vụ án mạng ngày một gia tăng khiến Riko phải tự mình lao vào vòng xoáy chết chóc để lý giải “Cõi Nguyền” rốt cuộc được gieo rắc từ đâu và làm cách nào để bản thân không trở thành nạn nhân tiếp theo.','Ken\'ichi Ugana','Yukino Kaizu, YU, Yutaka Kyan, Tammy Lin, Mimi Shao, Ray Fan, Mondo Otani, Chen Wan-hao, Yuhei Shirakawa, Raion Yoza, Shiho, 艾瑪, Reika Oozeki, Hironobu Nomura, Yasukaze Motomiya',89,'2026-10-23','T18','posters/coi-nguyen.webp','https://www.youtube.com/watch?v=zsMuQUkduug','now_showing','2026-10-27 08:46:51','2026-10-27 08:46:51',NULL),(5,'Oán Linh Đòi Mạng','oan-linh-doi-mang','Phim xoay quanh câu chuyện của gia đình Tomy (Andri Mashadi). Với mong muốn mang lại một cuộc sống tốt đẹp hơn cho vợ (Titi Kamal) và các con, Tomy quyết định gánh một khoản vay thế chấp lớn để mua căn nhà trong mơ tại khu phức hợp dân cư cao cấp mang tên Perumahan Laddaland.\n\nTuy nhiên, niềm vui chưa kéo dài được bao lâu thì hàng loạt hiện tượng rùng rợn xảy ra. Bắt đầu từ cái chết bất thường của người giúp việc trong nhà, những âm thanh kỳ lạ, các bóng ma ám ảnh xuất hiện dày đặc, cùng với những bí mật đen tối dần hé lộ đằng sau khu dân cư này. Khi các hộ gia đình khác lần lượt hoảng sợ tìm cách dọn đi, gia đình Tomy lại rơi vào thế kẹt buộc phải tìm cách sinh tồn giữa chốn ác mộng.','Awi Suryadi','Titi Kamal, Andri Mashadi, Anantya Rezky Kirana, Shakeel Fauzi Aisy, Delia Husein, Aufa Assagaf, Laras Sardi, Raffan Al Aryan, Adjis Doaibu, Arief Didu, Sri Yatun, Sarah Tumiwa, Zidni Hakim, Kiky Drajat, Farah Ramadhani, Callysta Novela, Jonathan Alvaro',98,'2026-10-23','T18','posters/oan-linh-doi-mang.webp','https://www.youtube.com/watch?v=ycdsf8OuqY0','now_showing','2026-10-27 08:46:51','2026-10-27 08:46:51',NULL),(6,'Bambi: Lãnh Địa Săn Mồi','bambi-lanh-dia-san-moi','Bộ phim kể về Bambi, một chú nai bị đột biến sau khi nai mẹ bị thợ săn sát hại và môi trường sống bị ô nhiễm nghiêm trọng. Trở thành một sinh vật khổng lồ và hung dữ, Bambi bắt đầu hành trình trả thù con người. Câu chuyện xoay quanh một người mẹ và con trai bị mắc kẹt giữa khu rừng, nơi họ trở thành con mồi của sinh vật đáng sợ này.','Dan Allen','Roxanne McKee, Tom Mulheron, Adrian Relph, Nicola Wright, Alex Cooke, Ewan Borthwick, Big Tobz, Joseph Greenwood, Russell Geoffrey Banks, Samira Mighty, Catherine Adams, Luke Cavendish, David Ambler',80,'2026-10-23','T16','posters/bambi-lanh-dia-san-moi.webp','https://www.youtube.com/watch?v=_6mbpOiCWw0','now_showing','2026-10-27 08:46:51','2026-10-27 08:46:51',NULL),(7,'Shaun the Sheep: Quái Lạ Ghé Nhà','shaun-the-sheep-quai-la-ghe-nha','Shaun the Sheep: Quái Lạ Ghé Nhà bắt đầu với sự cố Ông chủ vô tình phá hỏng vườn bí ngô mà đàn cừu đang chuẩn bị cho Halloween. Để cứu vãn tình hình, Shaun trổ tài làm “nhà khoa học”, nhưng thí nghiệm lại kéo theo hàng loạt rắc rối ngoài dự tính. Khi Ông chủ mất tích và một sinh vật bí ẩn xuất hiện trong rừng, cả đàn cừu lên đường tìm kiếm Ông chủ và đối mặt với một chuyến phiêu lưu vừa quái vừa nhộn.','Steve Cox, Matthew Walker','Justin Fletcher, John Sparkes, Nina Sosanya, Kate Harbour, Andy Nyman, Simon Greenall, Emma Tate, Rich Webber, Paul Whitehouse, Roman Kemp, Dani Dyer, Chris Morrell, Matthew Walker, Steve Cox',81,'2026-10-16','P','posters/shaun-the-sheep-quai-la-ghe-nha.webp','https://www.youtube.com/watch?v=8q6XZq8a0iA','now_showing','2026-10-27 08:46:51','2026-10-27 08:46:51',NULL),(8,'Bí Mật Bị Chôn Vùi','bi-mat-bi-chon-vui','Bí Mật Bị Chôn Vùi (Verity) được chuyển thể từ cuốn tiểu thuyết bán chạy nhất của Colleen Hoover. Bộ phim giật gân tâm lý đầy lôi cuốn này xoay quanh nữ nhà văn nổi tiếng Verity Crawford (Anne Hathaway). Lowen Ashleigh (Dakota Johnson) - nhà văn đang chật vật với sự nghiệp, được mời đến dinh thự hẻo lánh Crawford để viết thay. Tại đây, Lowen phát hiện những ghi chép ám ảnh, hé lộ những bí mật gây sốc về chồng Verity, Jeremy (Josh Hartnett), khiến cô dần lạc lối giữa hư cấu và thực tại, giữa thao túng và sức hút , cũng như giữa cơ hội và sự ám ảnh.','Michael Showalter','Dakota Johnson, Anne Hathaway, Josh Hartnett, Ismael Cruz Cordova, Brady Wagner, Irina Dvorovenko, K.K. Moggie, Michael Abbott Jr., Alex Cooper',117,'2026-10-16','T18','posters/bi-mat-bi-chon-vui.webp','https://www.youtube.com/watch?v=wBAco9LJ4To','now_showing','2026-10-27 08:46:51','2026-10-27 08:46:51',NULL),(9,'Street Fighter','street-fighter','Lấy bối cảnh năm 1993, Ryu và Ken, hai đấu sĩ từng xa cách bị kéo trở lại chiến đấu khi Chun-Li chiêu mộ họ tham gia giải Chiến Binh Thế Giới đầy khốc liệt. Nhưng đằng sau đó là một âm mưu chết chóc, buộc họ phải đối đầu với nhau và quá khứ của chính mình, nếu không tất cả sẽ CHẤM HẾT! Dưới sự chỉ đạo của đạo diễn Kitao Sakurai, Street Fighter mang những trận chiến game thùng lên màn ảnh rộng với các đòn thế quen thuộc cùng dàn nhân vật được yêu thích.','Kitao Sakurai','Noah Centineo, Andrew Koji, Callina Liang, Joe Anoa\'i, David Dastmalchian, Cody Rhodes, Andrew Schulz, Eric André, Vidyut Jammwal, Orville Peck, Olivier Richters, Hirooki Goto, Rayna Vallandingham, Alexander Volkanovski, 50 Cent, Jason Momoa',119,'2026-10-16','T16','posters/street-fighter.webp','https://www.youtube.com/watch?v=xwnZ_uvrFs0','now_showing','2026-10-27 08:46:51','2026-10-27 08:46:51',NULL),(10,'Án Mạng Xém Hoàn Hảo','an-mang-xem-hoan-hao','Trinh, cô nàng TikToker ngôn tình triệu view, tỉnh dậy giữa phim trường lạnh lẽo với cái đầu đau như búa bổ, mất trí nhớ và phát hiện xác của Yến (diễn viên) – tình địch đang bị nghi ngờ có gì mờ ám với diễn viên Khang (chồng sắp cưới). Đại (thám tử) được Trinh thuê theo dõi vụ ngoại tình lẻn vào giúp thì vấp ngã để lại dấu vân tay lên tử thi và vô tình bị bảo vệ bắt quả tang. Kể từ đây, liên tiếp những tình huống oái oăm mà cặp đôi “đũa lệch” phải đối mặt: chạy trốn khỏi cảnh sát dí sát gót và sát thủ rình rập, vừa cãi nhau tóe khói vừa phá án. Song Song đó, cả hai vô tình lật tẩy bí mật động trời của showbiz','Đức Nguyễn','Anh Tú Atus, DJ Mie, Vũ Ngọc Anh, Huy Khánh, Long Đẹp Trai, Sỹ Toàn',124,'2026-10-09','T18','posters/an-mang-xem-hoan-hao.webp','https://www.youtube.com/watch?v=IW-k9cMySWg','now_showing','2026-10-27 08:46:51','2026-10-27 08:46:51',NULL),(11,'Cá Voi Nuốt Chửng','ca-voi-nuot-chung','Câu chuyện kể về một thợ lặn, trong khi tìm kiếm hài cốt cha mình, đã bị một con cá voi nhà táng khổng lồ dài 24 mét, nặng 27 tấn nuốt chửng và chỉ có một giờ để thoát ra trước khi hết oxy.','Bronte Higgs',NULL,106,'2026-10-16','T13','posters/ca-voi-nuot-chung.webp','https://www.youtube.com/watch?v=CyoPI-UK9hw','now_showing','2026-10-27 08:46:51','2026-10-27 08:46:51',NULL),(12,'Người Mẹ Khác','nguoi-me-khac','Người Mẹ Khác theo chân Bela, cô bé 8 tuổi đang phải chứng kiến cuộc hôn nhân của cha mẹ dần tan vỡ. Giữa bầu không khí căng thẳng trong gia đình, một thực thể bí ẩn xuất hiện từ chiếc tủ quần áo trong phòng ngủ và bắt đầu ám ảnh cả ngôi nhà. Bela gọi nó là \"Người Mẹ Khác\", bởi sinh vật ấy mang gương mặt giống hệt mẹ ruột của mình. Khi ranh giới giữa người thân và thế lực tà ác dần bị xóa nhòa, cô bé buộc phải đối mặt với cơn ác mộng kinh hoàng ngay trong chính ngôi nhà của mình.','Rob Savage','Jessica Chastain, Arabella Olivia Clark, Jay Duplass, Dichen Lachman, Arian Moayed, Karen Allen, Sean Kaufman, Adam Silver, Carrie Dimaculangan, Travis Nelson, Hayley Spelman, Rosie A